// Stock is a point-in-time reading, not a window. It is labelled with the
// close of the last complete week so it lines up with the sales tally.

const now = $now.setZone('America/New_York');
const dayOfWeek = now.weekday % 7;
const currentWeekStart = now.minus({ days: dayOfWeek }).startOf('day');
const asOf = currentWeekStart.minus({ seconds: 1 });

const fmt = "yyyy-MM-dd'T'HH:mm:ssZZ";
const year = asOf.toFormat('yyyy');
const month = asOf.toFormat('MM-MMMM');
const fileName = asOf.toFormat('yyyy-MM-dd') + '-cigar-stock.csv';

return [{
  json: {
    as_of_label: asOf.toFormat('yyyy-MM-dd'),
    file_path: `business-decisions-data/cigar-stock/${year}/${month}/${fileName}`,
    generated_at: now.toFormat(fmt)
  }
}];

const cats = items.map(i => i.json);
const match = cats.find(c => String(c.name || '').trim().toLowerCase() === 'cigars');

if (!match) {
  throw new Error('No category named "Cigars" found. Categories present: ' + cats.map(c => c.name).join(', '));
}

return [{ json: { category_id: match.category_id, category_name: match.name } }];

// Reduce full item objects (images, variations, tier pricing, location blocks)
// down to the four fields the analyst needs. This is the only large payload
// in this execution; no sales data is present.

const win = $('Build Window').all()[0].json;
const itemRows = items.map(i => i.json);

if (!itemRows.length) {
  throw new Error('No cigar items returned from /items.');
}

function onHandFor(item) {
  const loc = item.locations;
  if (!loc || typeof loc !== 'object') return 0;
  let total = 0;
  for (const k of Object.keys(loc)) {
    const n = Number(loc[k] && loc[k].quantity);
    if (!isNaN(n)) total += n;
  }
  return total;
}

function csvCell(v) {
  const s = String(v === null || v === undefined ? '' : v);
  return /[",\n]/.test(s) ? '"' + s.replace(/"/g, '""') + '"' : s;
}

const lines = ['item_id,sku,name,on_hand,unit_cost'];
let carried = 0;

let skipped = 0;

for (const item of itemRows) {
  if (item.item_inactive === true) { skipped++; continue; }

  const onHand = Math.max(0, Math.round(onHandFor(item)));
  const cost = Number(item.cost_price || 0);
  const name = String(item.name || '').trim();

  // Drop catalog junk: blank names, and rows with no stock AND no cost.
  // Raffle entries and placeholder records look like this. A real cigar that
  // is merely out of stock still has a cost price, so it survives.
  if (!name) { skipped++; continue; }
  if (onHand === 0 && cost === 0) { skipped++; continue; }

  carried++;
  lines.push([
    csvCell(item.item_id),
    csvCell(item.item_number || item.item_id),
    csvCell(name),
    onHand,
    cost.toFixed(2)
  ].join(','));
}

return [{
  json: {
    file_path: win.file_path,
    as_of: win.as_of_label,
    carried_skus: carried,
    skipped_rows: skipped,
    fetched_rows: itemRows.length,
    commit_message: `Cigar stock snapshot ${win.as_of_label} (${carried} SKUs, ${skipped} filtered from ${itemRows.length} fetched)`,
    file_content: lines.join('\n') + '\n'
  }
}];

const now = $now.setZone('America/New_York');
const stamp = now.toFormat('yyyy-MM-dd HH:mm:ss ZZZZ');

const first = (items && items[0] && items[0].json) ? items[0].json : {};
const raw = first.error;

let message = 'No error message available';
let detail = '';

if (typeof raw === 'string') {
  message = raw;
  detail = raw;
} else if (raw && typeof raw === 'object') {
  message = raw.message || raw.description || raw.reason || message;
  try { detail = JSON.stringify(raw, null, 2).slice(0, 4000); } catch (e) { detail = 'Could not serialize error payload.'; }
} else {
  try { detail = JSON.stringify(first, null, 2).slice(0, 4000); } catch (e) { detail = 'Could not serialize item.'; }
}

let failedNode = 'unknown step';
try { if ($prevNode && $prevNode.name) failedNode = $prevNode.name; } catch (e) {}

const body = [
  '**Cigar Stock Snapshot failed.**',
  '',
  `- Failed step: \`${failedNode}\``,
  `- Time: ${stamp}`,
  `- Execution ID: ${$execution.id}`,
  '',
  '### Error',
  '```',
  String(message),
  '```',
  '',
  '### Raw payload',
  '```json',
  detail,
  '```',
  '',
  '---',
  'No stock file was written, so the Cigar Sales Tally has no stock figures to join against.'
].join('\n');

return [{
  json: {
    issue_title: `Cigar Stock Snapshot failed at ${failedNode} - ${now.toFormat('yyyy-MM-dd')}`,
    issue_body: body
  }
}];
